import pandas as pd
import matplotlib.pyplot as plt
import seaborn as sns
import numpy as np
import base64
from io import BytesIO
import os

# Set style for professional look
sns.set_theme(style="whitegrid", palette="muted")
plt.rcParams['figure.figsize'] = (10, 6)

def figure_to_base64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    return base64.b64encode(buf.getvalue()).decode('utf-8')

def generate_report():
    print("Loading data...")
    df = pd.read_csv('/app/benchmark/data.csv')

    # Pre-processing
    df['rated'] = df['rated'].astype(str).str.upper() == 'TRUE'
    df['white_rating'] = pd.to_numeric(df['white_rating'], errors='coerce')
    df['black_rating'] = pd.to_numeric(df['black_rating'], errors='coerce')
    df['turns'] = pd.to_numeric(df['turns'], errors='coerce')
    df['rating_diff'] = df['white_rating'] - df['black_rating']
    df['abs_rating_diff'] = df['rating_diff'].abs()

    def get_higher_rated_winner(row):
        if row['winner'] == 'draw': return 'draw'
        if row['rating_diff'] > 0 and row['winner'] == 'white': return 'higher'
        if row['rating_diff'] < 0 and row['winner'] == 'black': return 'higher'
        if row['rating_diff'] == 0: return 'equal'
        return 'lower'

    df['higher_rated_result'] = df.apply(get_higher_rated_winner, axis=1)

    df['rating_tier'] = pd.cut((df['white_rating'] + df['black_rating']) / 2, 
                               bins=[0, 1200, 1600, 2000, 3500], 
                               labels=['Beginner (<1200)', 'Intermediate (1200-1600)', 'Advanced (1600-2000)', 'Expert (2000+)'])

    # 1. Overview
    total_games = len(df)
    rated_pct = df['rated'].mean() * 100
    victory_dist = df['victory_status'].value_counts(normalize=True) * 100
    winner_dist = df['winner'].value_counts(normalize=True) * 100

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(14, 6))
    sns.barplot(x=victory_dist.index, y=victory_dist.values, ax=ax1, palette='Blues_d')
    ax1.set_title("Victory Status Distribution")
    ax1.set_ylabel("Percentage (%)")

    sns.barplot(x=winner_dist.index, y=winner_dist.values, ax=ax2, palette=['#e2e2e2', '#333333', '#888888'])
    ax2.set_title("Winner Distribution")
    ax2.set_ylabel("Percentage (%)")
    overview_chart = figure_to_base64(fig)

    # 2. Color Advantage
    white_wins = len(df[df['winner'] == 'white'])
    black_wins = len(df[df['winner'] == 'black'])
    decisive_games = white_wins + black_wins
    white_win_rate_decisive = (white_wins / decisive_games) * 100 if decisive_games > 0 else 0

    color_adv_tier = df[df['winner'] != 'draw'].groupby('rating_tier', observed=True)['winner'].value_counts(normalize=True).unstack() * 100
    fig, ax = plt.subplots(figsize=(10, 6))
    color_adv_tier.plot(kind='bar', stacked=False, ax=ax, color=['#333333', '#e2e2e2'])
    ax.set_title("Win Rate by Color and Rating Tier (Excluding Draws)")
    ax.set_ylabel("Win Rate (%)")
    ax.set_xlabel("Average Game Rating")
    ax.legend(title='Winner', labels=['Black', 'White'])
    plt.xticks(rotation=0)
    color_adv_chart = figure_to_base64(fig)

    # 3. Rating Dynamics
    fig, axes = plt.subplots(1, 2, figsize=(16, 6))
    sns.histplot(data=df, x='white_rating', color='#e2e2e2', label='White', kde=True, ax=axes[0], alpha=0.6)
    sns.histplot(data=df, x='black_rating', color='#333333', label='Black', kde=True, ax=axes[0], alpha=0.6)
    axes[0].set_title("Rating Distribution")
    axes[0].legend()

    # Rating diff bins
    df['diff_bin'] = pd.cut(df['abs_rating_diff'], bins=[-1, 50, 100, 200, 300, 500, 4000], 
                            labels=['0-50', '51-100', '101-200', '201-300', '301-500', '500+'])

    win_prob = df[df['higher_rated_result'].isin(['higher', 'lower'])].groupby('diff_bin', observed=True)['higher_rated_result'].apply(lambda x: (x == 'higher').mean() * 100)

    sns.barplot(x=win_prob.index, y=win_prob.values, ax=axes[1], palette='rocket')
    axes[1].set_title("Higher-Rated Player Win Probability by Rating Gap")
    axes[1].set_ylabel("Win Probability (%)")
    axes[1].set_xlabel("Absolute Rating Difference")
    rating_dyn_chart = figure_to_base64(fig)

    # Average game length by victory status and rating tier
    avg_length = df.pivot_table(values='turns', index='rating_tier', columns='victory_status', aggfunc='mean', observed=True)
    fig, ax = plt.subplots(figsize=(10, 6))
    sns.heatmap(avg_length, annot=True, fmt=".1f", cmap="YlGnBu", ax=ax)
    ax.set_title("Average Game Length (Turns) by Status and Rating Tier")
    avg_length_chart = figure_to_base64(fig)

    # 4. Opening Strategy
    top_openings = df['opening_name'].value_counts().nlargest(15).index
    df_top_open = df[df['opening_name'].isin(top_openings)]
    opening_stats = df_top_open.groupby('opening_name')['winner'].value_counts(normalize=True).unstack().fillna(0) * 100
    opening_stats = opening_stats[['white', 'black', 'draw']].sort_values(by='white', ascending=False)

    fig, ax = plt.subplots(figsize=(14, 8))
    opening_stats.plot(kind='barh', stacked=True, ax=ax, color=['#e2e2e2', '#333333', '#888888'])
    ax.set_title("Win Rates of Top 15 Openings")
    ax.set_xlabel("Percentage (%)")
    ax.set_ylabel("Opening Name")
    ax.legend(title='Winner', loc='upper right')
    top_openings_chart = figure_to_base64(fig)

    # 5. Time Control
    top_time_controls = df['increment_code'].value_counts().nlargest(8).index
    df_time = df[df['increment_code'].isin(top_time_controls)]
    time_status = df_time.groupby('increment_code')['victory_status'].value_counts(normalize=True).unstack().fillna(0) * 100

    # Sort by frequency of time control
    time_status = time_status.reindex(top_time_controls)

    fig, ax = plt.subplots(figsize=(12, 6))
    time_status.plot(kind='bar', stacked=True, ax=ax, cmap='viridis')
    ax.set_title("Victory Status by Top Time Controls")
    ax.set_ylabel("Percentage (%)")
    ax.set_xlabel("Time Control (Base+Increment)")
    plt.xticks(rotation=45)
    ax.legend(title='Victory Status')
    time_control_chart = figure_to_base64(fig)

    # Build HTML
    html = f"""<!DOCTYPE html>
<html lang="en">
<head>
